// TaxpayerEstimate Informational estimate of one month (derived on every read; same records, inputs, parameters and engine version → byte-identical JSON). `due_date` is day 17 of the next month (after the bimester for 621), moved to the next business day (CFF 12 ⚠️, "sujeto a confirmación"); RFC-digit grace days are not applied. `parameter_set` is the set of the period (each regime repeats it).
//
// Examples: {"disclaimers":[{"code":"not_tax_advice","severity":"info","text":"Estimación informativa. No sustituye la declaración ante el SAT ni la asesoría de un contador. Cálculo basado en LISR, LIVA, LIF 2026 y Anexo 8 RMF 2026."}],"due_date":"2026-04-17","engine_version":"1.0.0","figures_fingerprint":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb202603","legend":"Esto es un aproximado. No todos los gastos aplican para tu giro comercial.","parameter_set":{"fiscal_year":2026,"version":1},"period":"2026-03","records_fingerprint":"3f6c2a9e8d7b1c4f5a0e9d8c7b6a5f4e3d2c1b0a9f8e7d6c5b4a3f2e1d0c9b8a","regimes":[{"cpa_review_pending":false,"cpa_topics":[],"explanation":null,"isr":{"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096},"iva_components":{"charged_collected_cents":480000,"creditable_paid_cents":160000,"definitive_excluded_cents":0,"withheld_from_taxpayer_cents":106667},"missing_inputs":[],"parameter_set":{"fiscal_year":2026,"version":1},"regime_code":"612","regime_name":"Actividades Empresariales y Profesionales","status":"complete","treatment":"full","withheld_to_remit_cents":0}],"taxpayer_id":"0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80","totals":{"isr":{"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096},"iva":{"amount_cents":213333,"outcome":"payable","payable_rounded_cents":213333},"total_payable_rounded_cents":228429,"withholdings_to_remit_cents":0}}
type TaxpayerEstimate struct {
	Disclaimers []Disclaimer       `json:"disclaimers"`
	DueDate     openapi_types.Date `json:"due_date"`

	// EngineVersion Version of the tax engine that produced an estimate (`TaxpayerEstimate.engine_version`, opaque to the client). Bumped whenever an engine change can move a figure.
	//
	// Examples: 1.0.1
	EngineVersion EngineVersion `json:"engine_version"`

	// FiguresFingerprint SHA-256 (lower-case hex) over a canonical text of the figures the user sees for the month: totals (ISR, IVA payable / in favor, withholdings to remit, total), each regime's code, status, ISR, IVA and withholdings, `cpa_review_pending` and the due date. Versions, texts, explanations, citations and breakdown line order are excluded, so an input or engine change that leaves every figure identical keeps it (M8 OQ-H4). Computed in the M5 domain next to `RecordsFingerprint` (one golden-tested function). Changing the canonical text is an ADR-0002 amendment with a one-time re-baseline of stored views.
	//
	// Examples: bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb202606
	FiguresFingerprint FiguresFingerprint `json:"figures_fingerprint"`

	// Legend Mandatory legend; must be shown on every estimate surface.
	Legend Legend `json:"legend"`

	// ParameterSet The tax parameter set used (embedded `params/<fiscal_year>/v<version>.yaml`, ADR-0002 §3): the highest published version of the period's fiscal year, or the previous year's with `provisional_parameters`.
	//
	// Examples: {"fiscal_year":2026,"version":1}
	ParameterSet ParameterSetRef `json:"parameter_set"`

	// Period Examples: 2026-09
	Period Period `json:"period"`

	// RecordsFingerprint SHA-256 (lower-case hex) over the canonical aggregated input, the parameter version and the engine version (ADR-0002 §5). Equal fingerprints mean an identical estimate. M8 stores it with each view only to explain *why* a month changed (`HistoryChangeReason`); the changed marker itself is driven by `FiguresFingerprint`.
	//
	// Examples: 3f6c2a9e8d7b1c4f5a0e9d8c7b6a5f4e3d2c1b0a9f8e7d6c5b4a3f2e1d0c9b8a
	RecordsFingerprint RecordsFingerprint `json:"records_fingerprint"`
	Regimes            []RegimeEstimate   `json:"regimes"`

	// TaxpayerId Examples: 0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80
	TaxpayerId Uuid `json:"taxpayer_id"`

	// Totals Taxpayer-level totals; they carry no status (the client shows "Incompleto" when any regime is `incomplete`). `total_payable_rounded_cents = isr.payable_rounded_cents + iva.payable_rounded_cents + withholdings_to_remit_cents`.
	//
	// Examples: {"isr":{"amount_cents":15096,"outcome":"payable","payable_rounded_cents":15096},"iva":{"amount_cents":213333,"outcome":"payable","payable_rounded_cents":213333},"total_payable_rounded_cents":228429,"withholdings_to_remit_cents":0}
	Totals EstimateTotals `json:"totals"`
}

// TaxpayerEstimateStatus Taxpayer-level status of one month's estimate, derived server-side from its regimes with the M5 precedence: `informational` (every regime informational) > `incomplete` (any regime incomplete) > `partial` (any partial) > `complete`; `none` when the taxpayer holds no regime that month (`regimes: []`).
type TaxpayerEstimateStatus string

// TaxpayerList Examples: {"items":[{"archived_at":null,"created_at":"2026-10-13T16:05:00Z","display_name":"Ana (personal)","id":"0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80","person_type":"fisica","regimes":[{"end_period":null,"income_basis":"cash","name":"Personas Físicas con Actividades Empresariales y Profesionales","options":{"iva_fully_taxable":true},"regime_code":"612","start_period":"2026-01","treatment":"full"}],"rfc_masked":"GOMA******AB6"},{"archived_at":null,"created_at":"2026-10-13T16:20:00Z","display_name":"Empresa Ejemplo","id":"0199d4a2-9a10-7d55-b2c3-4d5e6f7a8b91","person_type":"moral","regimes":[{"end_period":null,"income_basis":"accrual","name":"General de Ley Personas Morales","options":{"iva_fully_taxable":true},"regime_code":"601","start_period":"2026-01","treatment":"full"}],"rfc_masked":"EEJ******QK2"}]}
type TaxpayerList struct {
	Items []Taxpayer `json:"items"`
}

// TaxpayerRegime A regime the taxpayer holds over `[start_period, end_period]` (open end while `end_period` is `null`). `options` always carries every option of the regime, defaults included. `name`, `treatment` and `income_basis` are the catalog's (`Regime`) for the taxpayer's person type, embedded so the record forms need no catalog round-trip.
//
// Examples: {"end_period":null,"income_basis":"cash","name":"Arrendamiento","options":{"deduction_mode":"blind_35"},"regime_code":"606","start_period":"2026-01","treatment":"full"}
type TaxpayerRegime struct {
	EndPeriod *Period `json:"end_period"`

	// IncomeBasis Which date books an income of the regime for ISR (MODULE-incomes §2.2): `cash` books on `collected_on`, `accrual` on `invoiced_on` (which is then required). Catalog data (`regimes.income_basis`), never a switch on the regime code: `accrual` is the personas morales of Título II (601, 620, 622, 623, 624); `cash` is every persona física regime, RESICO PM (626), 603 and 610. IVA is always cash (LIVA 1-B) whatever the basis. Added in 0.16.0 so the income form no longer mirrors the catalog in code.
	IncomeBasis IncomeBasis `json:"income_basis"`
	Name        string      `json:"name"`

	// Options Values keyed by `RegimeOptionDef.key`; validated server-side against the regime's `option_defs` (`unknown_option`, `invalid_option`, `required`).
	//
	// Examples: {"deduction_mode":"blind_35"}
	Options RegimeOptions `json:"options"`

	// RegimeCode SAT c_RegimenFiscal code.
	//
	// Examples: 612
	RegimeCode RegimeCode `json:"regime_code"`

	// StartPeriod Examples: 2026-09
	StartPeriod Period `json:"start_period"`

	// Treatment Support level of a regime: `full` (estimated), `partial` (some taxes only, e.g. IVA) or `informational` (selectable, not estimated; carries an explanation).
	Treatment Treatment `json:"treatment"`

	// Warnings Non-blocking notices about the regime just added. Present only on the `addTaxpayerRegime` response, and only when non-empty; never stored, never on reads or inside `Taxpayer.regimes`.
	Warnings *[]Warning `json:"warnings,omitempty"`
}

// TaxpayerRegimeCreate Examples: {"options":{"deduction_mode":"blind_35"},"regime_code":"606","start_period":"2026-01"}
type TaxpayerRegimeCreate struct {
	// Options Values keyed by `RegimeOptionDef.key`; validated server-side against the regime's `option_defs` (`unknown_option`, `invalid_option`, `required`).
	//
	// Examples: {"deduction_mode":"blind_35"}
	Options *RegimeOptions `json:"options,omitempty"`

	// RegimeCode SAT c_RegimenFiscal code.
	//
	// Examples: 612
	RegimeCode RegimeCode `json:"regime_code"`

	// StartPeriod Examples: 2026-09
	StartPeriod *Period `json:"start_period,omitempty"`
}

// TaxpayerRegimeUpdate Examples: {"options":{"deduction_mode":"actual"}}
type TaxpayerRegimeUpdate struct {
	// Options Values keyed by `RegimeOptionDef.key`; validated server-side against the regime's `option_defs` (`unknown_option`, `invalid_option`, `required`).
	//
	// Examples: {"deduction_mode":"blind_35"}
	Options RegimeOptions `json:"options"`
}

// TaxpayerUpdate Person type is immutable. `rfc` corrects a mistyped RFC of the same person type (OQ-1).
//
// Examples: {"display_name":"Ana (negocio)"}
type TaxpayerUpdate struct {
	// DisplayName Trimmed and NFC-normalized; no invisible characters (control, format such as zero-width or bidi controls, line or paragraph separators; a zero-width joiner inside an emoji sequence is allowed): `400 validation_failed`, field code `invisible_characters`.
	DisplayName *string `json:"display_name,omitempty"`

	// Rfc RFC as typed: spaces, dashes and lower case are accepted and normalized server-side (trim, upper-case, NFC, inner spaces and `-` removed). The edge bounds only the length, so every RFC rule is reported on `rfc` with a domain code: `rfc_length_mismatch` (13 for física, 12 for moral), `rfc_format`, `rfc_date`, `rfc_generic`. A SAT módulo 11 check-digit mismatch is not an error (D-RFC): it is accepted with the warning `rfc_check_digit_mismatch`. Never echoed back.
	//
	// Examples: GOMA800101AB6
	Rfc *RfcInput `json:"rfc,omitempty"`
}

